import { ApplicationError } from "../../application/errors";

function asRecord(body: unknown): Record<string, unknown> {
  return typeof body === "object" && body !== null
    ? (body as Record<string, unknown>)
    : {};
}

export function requiredString(body: unknown, key: string): string {
  const value = asRecord(body)[key];
  if (typeof value !== "string") {
    throw new ApplicationError("validation", `${key} is required and must be a string`);
  }
  return value;
}

export function optionalString(body: unknown, key: string): string | undefined {
  const value = asRecord(body)[key];
  if (value === undefined || value === null) {
    return undefined;
  }
  if (typeof value !== "string") {
    throw new ApplicationError("validation", `${key} must be a string`);
  }
  return value;
}

export function queryString(value: unknown): string | undefined {
  return typeof value === "string" ? value : undefined;
}

